CREATE TABLE IF NOT EXISTS gs_shops (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL);
CREATE TABLE IF NOT EXISTS gs_owners (id BIGINT AUTO_INCREMENT PRIMARY KEY, shop_id BIGINT NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, FOREIGN KEY (shop_id) REFERENCES gs_shops(id));
CREATE TABLE IF NOT EXISTS gs_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, shop_id BIGINT NOT NULL, name VARCHAR(150) NOT NULL, original_price INT NOT NULL, sale_price INT NOT NULL, quantity INT NOT NULL, deadline DATETIME NOT NULL, image MEDIUMBLOB, sold_out BOOLEAN NOT NULL DEFAULT FALSE, deleted BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (shop_id) REFERENCES gs_shops(id));
CREATE TABLE IF NOT EXISTS gs_bookings (id BIGINT AUTO_INCREMENT PRIMARY KEY, item_id BIGINT NOT NULL, customer_token VARCHAR(64) NOT NULL, customer_name VARCHAR(150) NOT NULL, customer_email VARCHAR(254) NOT NULL, customer_phone VARCHAR(40) NOT NULL, quantity INT NOT NULL, unit_price INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'REQUESTED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (item_id) REFERENCES gs_items(id));
